{
  "items": [
    {
      "name": "MvPolynomial.degreeOf",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (n : σ) (p : MvPolynomial σ R) : ℕ",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_le_totalDegree",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (f : MvPolynomial σ R) (i : σ) : MvPolynomial.degreeOf i f ≤ f.totalDegree",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_X_self",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [Nontrivial R] (i : σ) : MvPolynomial.degreeOf i (MvPolynomial.X i) = 1",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_X_of_ne",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {i j : σ} (h : i ≠ j) : MvPolynomial.degreeOf i (MvPolynomial.X j) = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_def",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (n : σ) (p : MvPolynomial σ R) : MvPolynomial.degreeOf n p = Multiset.count n p.degrees",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_X",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (i j : σ) [Nontrivial R] : MvPolynomial.degreeOf i (MvPolynomial.X j) = if i = j then 1 else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_one",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (n : σ) : MvPolynomial.degreeOf n 1 = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_zero",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (n : σ) : MvPolynomial.degreeOf n 0 = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    }
  ]
}
